(()=>{'use strict';const mobile=matchMedia('(max-width:800px)'),panel=document.querySelector('#detail-panel'),contact=document.querySelector('.contact.motion-outro'),field=contact.querySelector('.outro-field');let titles=[],frame=0;
function update(){cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{for(const h of titles){h.style.removeProperty('font-size');if(!mobile.matches||!h.clientWidth)continue;const base=parseFloat(getComputedStyle(h).fontSize),width=h.clientWidth;if(h.scrollWidth>width)h.style.fontSize=(Math.floor(base*(width-1)/h.scrollWidth*100)/100)+'px';}
if(!mobile.matches){field.style.removeProperty('clip-path');return;}const r=contact.getBoundingClientRect(),f=field.getBoundingClientRect(),border=getComputedStyle(contact,'::before'),inset=name=>parseFloat(border[name])||0;const top=Math.max(0,r.top+inset('top')+1-f.top),right=Math.max(0,f.right-(r.right-inset('right')-1)),bottom=Math.max(0,f.bottom-(r.bottom-inset('bottom')-1)),left=Math.max(0,r.left+inset('left')+1-f.left);field.style.clipPath=`inset(${top}px ${right}px ${bottom}px ${left}px)`;});}
const titleObserver=new ResizeObserver(update);function scan(){titleObserver.disconnect();titles=[...panel.querySelectorAll('.noodle-study-copy h3')];titles.forEach(h=>titleObserver.observe(h.parentElement));update();}new MutationObserver(scan).observe(panel,{childList:true});const boundsObserver=new ResizeObserver(update);boundsObserver.observe(contact);boundsObserver.observe(field);mobile.addEventListener('change',update);window.addEventListener('resize',update);document.fonts.ready.then(update);scan();})();
